function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 1000) return 's needs 1 to 1000 letters.';
  if (!/^[a-z]+$/.test(s)) return 's uses only lowercase English letters.';
  if (!Number.isInteger(k) || k < 1 || k > 1000) return 'k is a whole number from 1 to 1000.';
  return null;
}

