function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const vowels = 'aeiou';
  const consonants = 'bcdfghjklmnpqrstvwxyz';
  const n = size === 'large' ? int(900, 1000) : int(1, 12);
  const share = [0.5, 0.5, 0.3, 0.7][int(0, 3)];
  let s = '';
  for (let i = 0; i < n; i++) s += rand() < share ? vowels[int(0, 4)] : consonants[int(0, 20)];
  const k = size === 'large'
    ? [1, 2, 4, 9, 36, 100, int(1, 1000)][int(0, 6)]
    : (rand() < 0.8 ? int(1, 9) : int(1, 1000));
  return [s, k];
}
